CREATE FUNCTION public.get_eligible_player_pool(input_team character varying) RETURNS TABLE(player_id integer, player_name character varying, team character varying, role character varying, last_match_date date, selection_pool character varying)
    LANGUAGE plpgsql
    AS $$
BEGIN

RETURN QUERY

WITH last_played AS (
    SELECT
        x.player_id,
        MAX(x.match_date) AS last_played_date
    FROM (
        SELECT
            b.player_id,
            m.match_date
        FROM batting_match_stats b
        JOIN matches m
            ON b.match_id = m.match_id

        UNION ALL

        SELECT
            bw.player_id,
            m.match_date
        FROM bowling_match_stats bw
        JOIN matches m
            ON bw.match_id = m.match_id
    ) x

    GROUP BY
        x.player_id
),

active_players AS (
    SELECT
        p.player_id AS pid,
        p.name AS pname,
        p.team AS pteam,
        p.role AS prole,
        lp.last_played_date

    FROM players p

    LEFT JOIN last_played lp
        ON p.player_id = lp.player_id

    WHERE p.team = input_team
      AND p.is_active = TRUE
),

pool_count AS (
    SELECT
        COUNT(*) FILTER (
            WHERE ap.last_played_date >=
                CURRENT_DATE - INTERVAL '6 months'
        ) AS six_month_count,

        COUNT(*) FILTER (
            WHERE ap.last_played_date >=
                CURRENT_DATE - INTERVAL '12 months'
        ) AS twelve_month_count

    FROM active_players ap
)

SELECT
    ap.pid::INTEGER,
    ap.pname::VARCHAR,
    ap.pteam::VARCHAR,
    ap.prole::VARCHAR,
    ap.last_played_date::DATE,

    CASE
        WHEN pc.six_month_count >= 15
            THEN 'Last 6 Months'

        WHEN pc.twelve_month_count >= 15
            THEN 'Last 12 Months'

        ELSE
            'All Active Players'
    END::VARCHAR

FROM active_players ap

CROSS JOIN pool_count pc

WHERE
    (
        pc.six_month_count >= 15
        AND ap.last_played_date >=
            CURRENT_DATE - INTERVAL '6 months'
    )

    OR

    (
        pc.six_month_count < 15
        AND pc.twelve_month_count >= 15
        AND ap.last_played_date >=
            CURRENT_DATE - INTERVAL '12 months'
    )

    OR

    (
        pc.six_month_count < 15
        AND pc.twelve_month_count < 15
    )

ORDER BY
    ap.last_played_date DESC NULLS LAST;

END;
$$;


ALTER FUNCTION public.get_eligible_player_pool(input_team character varying) OWNER TO cricket_admin;

