-- Name: get_future_match_features(character varying, character varying, character varying, character varying, character varying, integer[], integer[]); Type: FUNCTION; Schema: public; Owner: cricket_admin
--

CREATE FUNCTION public.get_future_match_features(input_team1 character varying, input_team2 character varying, input_venue character varying, input_toss_winner character varying, input_toss_decision character varying, input_team1_xi integer[], input_team2_xi integer[]) RETURNS TABLE(team1_win_percentage_last_5 numeric, team2_win_percentage_last_5 numeric, team1_avg_runs_last_5 numeric, team2_avg_runs_last_5 numeric, team1_avg_wickets_last_5 numeric, team2_avg_wickets_last_5 numeric, team1_bowling_economy_last_5 numeric, team2_bowling_economy_last_5 numeric, previous_h2h_matches bigint, team1_h2h_win_percentage numeric, team2_h2h_win_percentage numeric, team1_previous_venue_matches bigint, team1_venue_win_percentage numeric, team2_previous_venue_matches bigint, team2_venue_win_percentage numeric, team1_won_toss integer, toss_decision_field integer, team1_xi_runs_previous_5 numeric, team2_xi_runs_previous_5 numeric, team1_xi_batting_strike_rate numeric, team2_xi_batting_strike_rate numeric, team1_xi_runs_per_innings numeric, team2_xi_runs_per_innings numeric, team1_xi_wickets_previous_5 numeric, team2_xi_wickets_previous_5 numeric, team1_xi_wickets_per_bowling_match numeric, team2_xi_wickets_per_bowling_match numeric, team1_xi_bowling_economy numeric, team2_xi_bowling_economy numeric)
    LANGUAGE sql
    AS $$

WITH

-- ==================================================
-- TEAM 1 LAST 5 WIN %
-- ==================================================

team1_last5 AS (

    SELECT
        COUNT(*) AS matches_used,

        COUNT(*) FILTER (
            WHERE x.winner = input_team1
        ) AS wins

    FROM (

        SELECT
            m.match_id,
            m.match_date,
            m.winner

        FROM matches m

        WHERE m.winner IS NOT NULL

          AND (
              m.team1 = input_team1
              OR
              m.team2 = input_team1
          )

        ORDER BY
            m.match_date DESC,
            m.match_id DESC

        LIMIT 5

    ) x
),

-- ==================================================
-- TEAM 2 LAST 5 WIN %
-- ==================================================

team2_last5 AS (

    SELECT
        COUNT(*) AS matches_used,

        COUNT(*) FILTER (
            WHERE x.winner = input_team2
        ) AS wins

    FROM (

        SELECT
            m.match_id,
            m.match_date,
            m.winner

        FROM matches m

        WHERE m.winner IS NOT NULL

          AND (
              m.team1 = input_team2
              OR
              m.team2 = input_team2
          )

        ORDER BY
            m.match_date DESC,
            m.match_id DESC

        LIMIT 5

    ) x
),

-- ==================================================
-- CURRENT TEAM FORM
-- ==================================================

team1_strength AS (

    SELECT *
    FROM team_recent_strength
    WHERE team = input_team1
),

team2_strength AS (

    SELECT *
    FROM team_recent_strength
    WHERE team = input_team2
),

-- ==================================================
-- H2H
-- ==================================================

h2h AS (

    SELECT *
    FROM team_vs_team_stats

    WHERE team_a = LEAST(
        input_team1,
        input_team2
    )

    AND team_b = GREATEST(
        input_team1,
        input_team2
    )

    LIMIT 1
),

-- ==================================================
-- VENUE
-- ==================================================

venue1 AS (

    SELECT *
    FROM team_venue_stats

    WHERE team = input_team1
      AND venue = input_venue

    LIMIT 1
),

venue2 AS (

    SELECT *
    FROM team_venue_stats

    WHERE team = input_team2
      AND venue = input_venue

    LIMIT 1
),

-- ==================================================
-- XI STRENGTH
-- ==================================================

xi1 AS (

    SELECT *
    FROM get_xi_strength(
        input_team1_xi
    )
),

xi2 AS (

    SELECT *
    FROM get_xi_strength(
        input_team2_xi
    )
)

SELECT

    -- ==================================================
    -- RECENT WIN %
    -- ==================================================

    ROUND(
        (
            t1f.wins::NUMERIC
            * 100
            /
            NULLIF(
                t1f.matches_used,
                0
            )
        ),
        2
    ),

    ROUND(
        (
            t2f.wins::NUMERIC
            * 100
            /
            NULLIF(
                t2f.matches_used,
                0
            )
        ),
        2
    ),

    -- ==================================================
    -- RECENT SCORING
    -- ==================================================

    t1.avg_score_last_5_matches,

    t2.avg_score_last_5_matches,

    -- ==================================================
    -- RECENT WICKETS
    -- ==================================================

    ROUND(
        t1.wickets_last_5_matches::NUMERIC
        /
        NULLIF(
            t1.matches_used,
            0
        ),
        2
    ),

    ROUND(
        t2.wickets_last_5_matches::NUMERIC
        /
        NULLIF(
            t2.matches_used,
            0
        ),
        2
    ),

    -- ==================================================
    -- RECENT ECONOMY
    -- ==================================================

    t1.economy_last_5_matches,

    t2.economy_last_5_matches,

    -- ==================================================
    -- H2H
    -- ==================================================

    COALESCE(
        h.matches_played,
        0
    )::BIGINT,

    CASE

        WHEN h.team_a = input_team1
            THEN h.team_a_win_percentage

        WHEN h.team_b = input_team1
            THEN h.team_b_win_percentage

        ELSE NULL

    END,

    CASE

        WHEN h.team_a = input_team2
            THEN h.team_a_win_percentage

        WHEN h.team_b = input_team2
            THEN h.team_b_win_percentage

        ELSE NULL

    END,

    -- ==================================================
    -- VENUE
    -- ==================================================

    COALESCE(
        v1.matches_played,
        0
    )::BIGINT,

    v1.win_percentage,

    COALESCE(
        v2.matches_played,
        0
    )::BIGINT,

    v2.win_percentage,

    -- ==================================================
    -- TOSS
    -- ==================================================

    CASE
        WHEN input_toss_winner = input_team1
            THEN 1
        ELSE 0
    END,

    CASE
        WHEN LOWER(input_toss_decision) = 'field'
            THEN 1
        ELSE 0
    END,

    -- ==================================================
    -- TEAM 1 XI
    -- ==================================================

    x1.xi_runs_previous_5,

    x2.xi_runs_previous_5,

    x1.xi_batting_strike_rate,

    x2.xi_batting_strike_rate,

    x1.xi_runs_per_innings,

    x2.xi_runs_per_innings,

    x1.xi_wickets_previous_5,

    x2.xi_wickets_previous_5,

    x1.xi_wickets_per_bowling_match,

    x2.xi_wickets_per_bowling_match,

    x1.xi_bowling_economy,

    x2.xi_bowling_economy

FROM team1_last5 t1f

CROSS JOIN team2_last5 t2f

CROSS JOIN team1_strength t1

CROSS JOIN team2_strength t2

CROSS JOIN xi1 x1

CROSS JOIN xi2 x2

LEFT JOIN h2h h
    ON TRUE

LEFT JOIN venue1 v1
    ON TRUE

LEFT JOIN venue2 v2
    ON TRUE;

$$;


ALTER FUNCTION public.get_future_match_features(input_team1 character varying, input_team2 character varying, input_venue character varying, input_toss_winner character varying, input_toss_decision character varying, input_team1_xi integer[], input_team2_xi integer[]) OWNER TO cricket_admin;

--
-- Name: get_latest_batting_form(integer); Type: FUNCTION; Schema: public; Owner: cricket_admin
--

CREATE FUNCTION public.get_latest_batting_form(input_player_id integer) RETURNS TABLE(player_id integer, player_name character varying, innings_used bigint, runs_last_5 numeric, balls_last_5 numeric, runs_per_innings numeric, strike_rate numeric)
    LANGUAGE sql
    AS $$

WITH match_batting AS (

    SELECT
        d.match_id,
        m.match_date,

        SUM(d.batter_runs) AS runs,

        COUNT(*) FILTER (
            WHERE COALESCE(d.wides, 0) = 0
        ) AS balls

    FROM deliveries d

    JOIN matches m
        ON d.match_id = m.match_id

    WHERE d.batter_id = input_player_id

    GROUP BY
        d.match_id,
        m.match_date
),

last_5 AS (

    SELECT
        mb.match_id,
        mb.match_date,
        mb.runs,
        mb.balls

    FROM match_batting mb

    ORDER BY
        mb.match_date DESC,
        mb.match_id DESC

    LIMIT 5
),

summary AS (

    SELECT
        COUNT(*) AS innings_used,

        COALESCE(
            SUM(runs),
            0
        ) AS total_runs,

        COALESCE(
            SUM(balls),
            0
        ) AS total_balls

    FROM last_5
)

SELECT
    p.player_id,

    p.name::VARCHAR,

    s.innings_used,

    s.total_runs::NUMERIC,

    s.total_balls::NUMERIC,

    ROUND(
        s.total_runs::NUMERIC
        /
        NULLIF(s.innings_used, 0),
        2
    ) AS runs_per_innings,

    ROUND(
        s.total_runs::NUMERIC * 100
        /
        NULLIF(s.total_balls, 0),
        2
    ) AS strike_rate

FROM players p

CROSS JOIN summary s

WHERE p.player_id = input_player_id;

$$;


ALTER FUNCTION public.get_latest_batting_form(input_player_id integer) OWNER TO cricket_admin;

--
-- Name: get_latest_bowling_form(integer); Type: FUNCTION; Schema: public; Owner: cricket_admin
--

CREATE FUNCTION public.get_latest_bowling_form(input_player_id integer) RETURNS TABLE(player_id integer, player_name character varying, matches_used bigint, wickets_last_5 numeric, balls_last_5 numeric, runs_conceded_last_5 numeric, wickets_per_match numeric, economy numeric)
    LANGUAGE sql
    AS $$

WITH match_bowling AS (

    SELECT
        d.match_id,
        m.match_date,

        COUNT(*) FILTER (
            WHERE COALESCE(d.wides, 0) = 0
              AND COALESCE(d.no_balls, 0) = 0
        ) AS legal_balls,

        SUM(
            d.total_runs
            - COALESCE(d.byes, 0)
            - COALESCE(d.leg_byes, 0)
        ) AS runs_conceded,

        COUNT(*) FILTER (
            WHERE d.is_wicket = TRUE
              AND d.dismissal_type NOT IN (
                  'run out',
                  'retired hurt',
                  'retired out',
                  'obstructing the field'
              )
        ) AS wickets

    FROM deliveries d

    JOIN matches m
        ON d.match_id = m.match_id

    WHERE d.bowler_id = input_player_id

    GROUP BY
        d.match_id,
        m.match_date
),

last_5 AS (

    SELECT
        mb.match_id,
        mb.match_date,
        mb.legal_balls,
        mb.runs_conceded,
        mb.wickets

    FROM match_bowling mb

    ORDER BY
        mb.match_date DESC,
        mb.match_id DESC

    LIMIT 5
),

summary AS (

    SELECT
        COUNT(*) AS matches_used,

        COALESCE(
            SUM(wickets),
            0
        ) AS total_wickets,

        COALESCE(
            SUM(legal_balls),
            0
        ) AS total_balls,

        COALESCE(
            SUM(runs_conceded),
            0
        ) AS total_runs_conceded

    FROM last_5
)

SELECT
    p.player_id,
    p.name::VARCHAR,

    s.matches_used,

    s.total_wickets::NUMERIC,

    s.total_balls::NUMERIC,

    s.total_runs_conceded::NUMERIC,

    ROUND(
        s.total_wickets::NUMERIC
        /
        NULLIF(s.matches_used, 0),
        2
    ) AS wickets_per_match,

    ROUND(
        s.total_runs_conceded::NUMERIC * 6
        /
        NULLIF(s.total_balls, 0),
        2
    ) AS economy

FROM players p

CROSS JOIN summary s

WHERE p.player_id = input_player_id;

$$;


ALTER FUNCTION public.get_latest_bowling_form(input_player_id integer) OWNER TO cricket_admin;

--
-- Name: get_xi_strength(integer[]); Type: FUNCTION; Schema: public; Owner: cricket_admin
--

CREATE FUNCTION public.get_xi_strength(input_player_ids integer[]) RETURNS TABLE(players_count bigint, xi_runs_previous_5 numeric, xi_batting_strike_rate numeric, xi_runs_per_innings numeric, xi_wickets_previous_5 numeric, xi_wickets_per_bowling_match numeric, xi_bowling_economy numeric)
    LANGUAGE sql
    AS $$

WITH selected_players AS (
    SELECT
        UNNEST(input_player_ids) AS player_id
),

batting AS (
    SELECT
        sp.player_id,

        bf.innings_used,
        bf.runs_last_5,
        bf.balls_last_5

    FROM selected_players sp

    LEFT JOIN LATERAL (
        SELECT *
        FROM get_latest_batting_form(sp.player_id)
    ) bf
        ON TRUE
),

bowling AS (
    SELECT
        sp.player_id,

        bw.matches_used,
        bw.wickets_last_5,
        bw.balls_last_5,
        bw.runs_conceded_last_5

    FROM selected_players sp

    LEFT JOIN LATERAL (
        SELECT *
        FROM get_latest_bowling_form(sp.player_id)
    ) bw
        ON TRUE
),

combined AS (
    SELECT
        sp.player_id,

        COALESCE(b.innings_used, 0)
            AS batting_innings,

        COALESCE(b.runs_last_5, 0)
            AS batting_runs,

        COALESCE(b.balls_last_5, 0)
            AS batting_balls,

        COALESCE(bo.matches_used, 0)
            AS bowling_matches,

        COALESCE(bo.wickets_last_5, 0)
            AS bowling_wickets,

        COALESCE(bo.balls_last_5, 0)
            AS bowling_balls,

        COALESCE(bo.runs_conceded_last_5, 0)
            AS bowling_runs

    FROM selected_players sp

    LEFT JOIN batting b
        ON sp.player_id = b.player_id

    LEFT JOIN bowling bo
        ON sp.player_id = bo.player_id
)

SELECT
    COUNT(*) AS players_count,

    SUM(batting_runs)::NUMERIC
        AS xi_runs_previous_5,

    ROUND(
        SUM(batting_runs)::NUMERIC * 100
        /
        NULLIF(
            SUM(batting_balls),
            0
        ),
        2
    ) AS xi_batting_strike_rate,

    ROUND(
        SUM(batting_runs)::NUMERIC
        /
        NULLIF(
            SUM(batting_innings),
            0
        ),
        2
    ) AS xi_runs_per_innings,

    SUM(bowling_wickets)::NUMERIC
        AS xi_wickets_previous_5,

    ROUND(
        SUM(bowling_wickets)::NUMERIC
        /
        NULLIF(
            SUM(bowling_matches),
            0
        ),
        2
    ) AS xi_wickets_per_bowling_match,

    ROUND(
        SUM(bowling_runs)::NUMERIC * 6
        /
        NULLIF(
            SUM(bowling_balls),
            0
        ),
        2
    ) AS xi_bowling_economy

FROM combined;

$$;


ALTER FUNCTION public.get_xi_strength(input_player_ids integer[]) OWNER TO cricket_admin;

--
-- Name: player_phase_score(character varying); Type: FUNCTION; Schema: public; Owner: cricket_admin
--

CREATE FUNCTION public.player_phase_score(input_team character varying) RETURNS TABLE(player_id integer, player_name character varying, role character varying, powerplay_score numeric, middle_score numeric, death_score numeric, overall_phase_score numeric)
    LANGUAGE sql
    AS $$

WITH batting AS (
    SELECT
        b.player_id,

        MAX(
            CASE
                WHEN b.phase = 'Powerplay'
                THEN (
                    b.runs * 0.5
                    + COALESCE(b.strike_rate, 0) * 0.5
                )
            END
        ) AS powerplay_batting,

        MAX(
            CASE
                WHEN b.phase = 'Middle'
                THEN (
                    b.runs * 0.5
                    + COALESCE(b.strike_rate, 0) * 0.5
                )
            END
        ) AS middle_batting,

        MAX(
            CASE
                WHEN b.phase = 'Death'
                THEN (
                    b.runs * 0.5
                    + COALESCE(b.strike_rate, 0) * 0.5
                )
            END
        ) AS death_batting

    FROM batter_phase_stats b

    WHERE b.team = input_team

    GROUP BY b.player_id
),

bowling AS (
    SELECT
        b.player_id,

        MAX(
            CASE
                WHEN b.phase = 'Powerplay'
                THEN (
                    b.wickets * 15
                    + b.dot_balls
                    + GREATEST(
                        0,
                        10 - COALESCE(b.economy, 10)
                    ) * 5
                )
            END
        ) AS powerplay_bowling,

        MAX(
            CASE
                WHEN b.phase = 'Middle'
                THEN (
                    b.wickets * 15
                    + b.dot_balls
                    + GREATEST(
                        0,
                        10 - COALESCE(b.economy, 10)
                    ) * 5
                )
            END
        ) AS middle_bowling,

        MAX(
            CASE
                WHEN b.phase = 'Death'
                THEN (
                    b.wickets * 15
                    + b.dot_balls
                    + GREATEST(
                        0,
                        10 - COALESCE(b.economy, 10)
                    ) * 5
                )
            END
        ) AS death_bowling

    FROM bowler_phase_stats b

    WHERE b.team = input_team

    GROUP BY b.player_id
),

combined AS (
    SELECT
        p.player_id,
        p.name,
        p.role,

        COALESCE(bt.powerplay_batting, 0)
        + COALESCE(bw.powerplay_bowling, 0)
            AS powerplay_raw,

        COALESCE(bt.middle_batting, 0)
        + COALESCE(bw.middle_bowling, 0)
            AS middle_raw,

        COALESCE(bt.death_batting, 0)
        + COALESCE(bw.death_bowling, 0)
            AS death_raw

    FROM players p

    LEFT JOIN batting bt
        ON p.player_id = bt.player_id

    LEFT JOIN bowling bw
        ON p.player_id = bw.player_id

    WHERE p.team = input_team
      AND p.is_active = TRUE
),

normalized AS (
    SELECT
        *,

        CASE
            WHEN MAX(powerplay_raw) OVER () =
                 MIN(powerplay_raw) OVER ()
                THEN 50
            ELSE
                (
                    (
                        powerplay_raw
                        - MIN(powerplay_raw) OVER ()
                    )
                    /
                    NULLIF(
                        MAX(powerplay_raw) OVER ()
                        - MIN(powerplay_raw) OVER (),
                        0
                    )
                ) * 100
        END AS powerplay_norm,

        CASE
            WHEN MAX(middle_raw) OVER () =
                 MIN(middle_raw) OVER ()
                THEN 50
            ELSE
                (
                    (
                        middle_raw
                        - MIN(middle_raw) OVER ()
                    )
                    /
                    NULLIF(
                        MAX(middle_raw) OVER ()
                        - MIN(middle_raw) OVER (),
                        0
                    )
                ) * 100
        END AS middle_norm,

        CASE
            WHEN MAX(death_raw) OVER () =
                 MIN(death_raw) OVER ()
                THEN 50
            ELSE
                (
                    (
                        death_raw
                        - MIN(death_raw) OVER ()
                    )
                    /
                    NULLIF(
                        MAX(death_raw) OVER ()
                        - MIN(death_raw) OVER (),
                        0
                    )
                ) * 100
        END AS death_norm

    FROM combined
)

SELECT
    n.player_id,
    n.name::VARCHAR,
    n.role::VARCHAR,

    ROUND(n.powerplay_norm::NUMERIC, 2),
    ROUND(n.middle_norm::NUMERIC, 2),
    ROUND(n.death_norm::NUMERIC, 2),

    ROUND(
        (
            n.powerplay_norm * 0.30
            +
            n.middle_norm * 0.35
            +
            n.death_norm * 0.35
        )::NUMERIC,
        2
    )

FROM normalized n

ORDER BY
    (
        n.powerplay_norm * 0.30
        +
        n.middle_norm * 0.35
        +
        n.death_norm * 0.35
    ) DESC;

$$;


