--
-- Name: player_score_vs_opponent(character varying, character varying); Type: FUNCTION; Schema: public; Owner: cricket_admin
--

CREATE FUNCTION public.player_score_vs_opponent(input_team character varying, input_opponent character varying) RETURNS TABLE(player_id integer, player_name character varying, role character varying, base_score numeric, vs_runs bigint, vs_balls bigint, vs_wickets bigint, vs_batting_sr numeric, opponent_score numeric, final_score numeric)
    LANGUAGE sql
    AS $$

WITH team_players AS (
    SELECT
        pac.player_id,
        pac.name,
        pac.role,
        pac.base_selection_score
    FROM player_actual_capability pac
    WHERE pac.team = input_team
),

batting_vs AS (
    SELECT
        h.batter_id AS player_id,

        SUM(h.runs) AS runs,
        SUM(h.balls_faced) AS balls,

        ROUND(
            SUM(h.runs)::NUMERIC * 100
            /
            NULLIF(SUM(h.balls_faced), 0),
            2
        ) AS strike_rate

    FROM batter_bowler_head_to_head h

    WHERE h.batter_team = input_team
      AND h.bowler_team = input_opponent

    GROUP BY h.batter_id
),

bowling_vs AS (
    SELECT
        d.bowler_id AS player_id,

        COUNT(*) FILTER (
            WHERE d.is_wicket = TRUE
              AND d.dismissal_type NOT IN (
                  'run out',
                  'retired hurt',
                  'retired out',
                  'obstructing the field'
              )
        ) AS wickets

    FROM deliveries d

    JOIN players batter
        ON d.batter_id = batter.player_id

    JOIN players bowler
        ON d.bowler_id = bowler.player_id

    WHERE bowler.team = input_team
      AND batter.team = input_opponent

    GROUP BY d.bowler_id
),

raw AS (
    SELECT
        tp.player_id,
        tp.name,
        tp.role,
        tp.base_selection_score,

        COALESCE(bv.runs, 0) AS vs_runs,
        COALESCE(bv.balls, 0) AS vs_balls,
        COALESCE(bw.wickets, 0) AS vs_wickets,
        COALESCE(bv.strike_rate, 0) AS vs_batting_sr,

        (
            COALESCE(bv.runs, 0) * 0.20
            +
            COALESCE(bv.strike_rate, 0) * 0.30
            +
            COALESCE(bw.wickets, 0) * 10
        ) AS raw_opponent_score

    FROM team_players tp

    LEFT JOIN batting_vs bv
        ON tp.player_id = bv.player_id

    LEFT JOIN bowling_vs bw
        ON tp.player_id = bw.player_id
),

normalized AS (
    SELECT
        *,

        CASE
            WHEN MAX(raw_opponent_score) OVER () =
                 MIN(raw_opponent_score) OVER ()
                THEN 50

            ELSE
                (
                    (
                        raw_opponent_score
                        -
                        MIN(raw_opponent_score) OVER ()
                    )
                    /
                    NULLIF(
                        MAX(raw_opponent_score) OVER ()
                        -
                        MIN(raw_opponent_score) OVER (),
                        0
                    )
                ) * 100
        END AS normalized_opponent_score

    FROM raw
)

SELECT
    n.player_id,
    n.name::VARCHAR,
    n.role::VARCHAR,

    ROUND(
        n.base_selection_score::NUMERIC,
        2
    ),

    n.vs_runs::BIGINT,
    n.vs_balls::BIGINT,
    n.vs_wickets::BIGINT,

    ROUND(
        n.vs_batting_sr::NUMERIC,
        2
    ),

    ROUND(
        n.normalized_opponent_score::NUMERIC,
        2
    ),

    ROUND(
        (
            n.base_selection_score * 0.75
            +
            n.normalized_opponent_score * 0.25
        )::NUMERIC,
        2
    )

FROM normalized n

ORDER BY
    (
        n.base_selection_score * 0.75
        +
        n.normalized_opponent_score * 0.25
    ) DESC;

$$;


ALTER FUNCTION public.player_score_vs_opponent(input_team character varying, input_opponent character varying) OWNER TO cricket_admin;

--
-- Name: player_score_vs_opponent_venue(character varying, character varying, text); Type: FUNCTION; Schema: public; Owner: cricket_admin
--

CREATE FUNCTION public.player_score_vs_opponent_venue(input_team character varying, input_opponent character varying, input_venue text) RETURNS TABLE(player_id integer, player_name character varying, role character varying, opponent_score numeric, venue_runs bigint, venue_balls bigint, venue_wickets bigint, venue_score numeric, final_score numeric)
    LANGUAGE sql
    AS $$

WITH opponent_scores AS (
    SELECT *
    FROM player_score_vs_opponent(
        input_team,
        input_opponent
    )
),

venue_batting AS (
    SELECT
        d.batter_id AS player_id,
        SUM(d.batter_runs) AS runs,

        COUNT(*) FILTER (
            WHERE d.wides = 0
        ) AS balls

    FROM deliveries d

    JOIN matches m
        ON d.match_id = m.match_id

    WHERE d.batting_team = input_team
      AND m.venue = input_venue

    GROUP BY d.batter_id
),

venue_bowling AS (
    SELECT
        d.bowler_id AS player_id,

        COUNT(*) FILTER (
            WHERE d.is_wicket = TRUE
              AND d.dismissal_type NOT IN (
                  'run out',
                  'retired hurt',
                  'retired out',
                  'obstructing the field'
              )
        ) AS wickets

    FROM deliveries d

    JOIN matches m
        ON d.match_id = m.match_id

    JOIN players p
        ON d.bowler_id = p.player_id

    WHERE p.team = input_team
      AND m.venue = input_venue

    GROUP BY d.bowler_id
),

raw AS (
    SELECT
        os.player_id,
        os.player_name,
        os.role,
        os.final_score AS opponent_score,

        COALESCE(vb.runs, 0) AS venue_runs,
        COALESCE(vb.balls, 0) AS venue_balls,
        COALESCE(vw.wickets, 0) AS venue_wickets,

        (
            COALESCE(vb.runs, 0) * 0.20
            +
            CASE
                WHEN COALESCE(vb.balls, 0) > 0
                THEN
                    (
                        COALESCE(vb.runs, 0)::NUMERIC
                        * 100
                        / vb.balls
                    ) * 0.20
                ELSE 0
            END
            +
            COALESCE(vw.wickets, 0) * 10
        ) AS raw_venue_score

    FROM opponent_scores os

    LEFT JOIN venue_batting vb
        ON os.player_id = vb.player_id

    LEFT JOIN venue_bowling vw
        ON os.player_id = vw.player_id
),

normalized AS (
    SELECT
        *,

        CASE
            WHEN MAX(raw_venue_score) OVER () =
                 MIN(raw_venue_score) OVER ()
                THEN 50

            ELSE
                (
                    (
                        raw_venue_score
                        -
                        MIN(raw_venue_score) OVER ()
                    )
                    /
                    NULLIF(
                        MAX(raw_venue_score) OVER ()
                        -
                        MIN(raw_venue_score) OVER (),
                        0
                    )
                ) * 100
        END AS normalized_venue_score

    FROM raw
)

SELECT
    n.player_id,
    n.player_name::VARCHAR,
    n.role::VARCHAR,

    ROUND(
        n.opponent_score::NUMERIC,
        2
    ),

    n.venue_runs::BIGINT,
    n.venue_balls::BIGINT,
    n.venue_wickets::BIGINT,

    ROUND(
        n.normalized_venue_score::NUMERIC,
        2
    ),

    ROUND(
        (
            n.opponent_score * 0.85
            +
            n.normalized_venue_score * 0.15
        )::NUMERIC,
        2
    )

FROM normalized n

ORDER BY
    (
        n.opponent_score * 0.85
        +
        n.normalized_venue_score * 0.15
    ) DESC;

$$;


ALTER FUNCTION public.player_score_vs_opponent_venue(input_team character varying, input_opponent character varying, input_venue text) OWNER TO cricket_admin;

--
-- Name: suggest_match_playing_xi(character varying, character varying, text); Type: FUNCTION; Schema: public; Owner: cricket_admin
--

CREATE FUNCTION public.suggest_match_playing_xi(input_team character varying, input_opponent character varying, input_venue text) RETURNS TABLE(player_id integer, player_name character varying, role character varying, match_score numeric, can_keep boolean, can_bat boolean, can_bowl boolean, top_order boolean, selection_reason character varying)
    LANGUAGE sql
    AS $$

WITH match_scores AS (
    SELECT
        v.player_id,
        v.player_name,
        v.role,

        ROUND(
            (
                v.final_score * 0.85
                +
                COALESCE(ph.overall_phase_score, 50) * 0.15
            )::NUMERIC,
            2
        ) AS match_score

    FROM player_score_vs_opponent_venue(
        input_team,
        input_opponent,
        input_venue
    ) v

    LEFT JOIN player_phase_score(input_team) ph
        ON v.player_id = ph.player_id
),

pool AS (
    SELECT
        ms.player_id,
        ms.player_name,
        ms.role,
        ms.match_score,

        pac.can_keep,
        pac.can_bat,
        pac.genuine_bowling_option AS can_bowl,
        pac.top_order_option AS top_order

    FROM match_scores ms

    JOIN player_actual_capability pac
        ON ms.player_id = pac.player_id

    WHERE pac.team = input_team
),

keeper AS (
    SELECT p.*
    FROM pool p
    WHERE p.can_keep = TRUE
    ORDER BY p.match_score DESC
    LIMIT 1
),

top_players AS (
    SELECT p.*
    FROM pool p
    WHERE p.top_order = TRUE
      AND p.player_id NOT IN (
          SELECT k.player_id
          FROM keeper k
      )
    ORDER BY p.match_score DESC
    LIMIT 2
),

bowling_players AS (
    SELECT p.*
    FROM pool p
    WHERE p.can_bowl = TRUE
      AND p.player_id NOT IN (
          SELECT k.player_id FROM keeper k

          UNION

          SELECT t.player_id FROM top_players t
      )
    ORDER BY p.match_score DESC
    LIMIT 5
),

initial_xi AS (
    SELECT * FROM keeper

    UNION

    SELECT * FROM top_players

    UNION

    SELECT * FROM bowling_players
),

remaining AS (
    SELECT
        p.*,

        ROW_NUMBER() OVER (
            ORDER BY p.match_score DESC
        ) AS rn

    FROM pool p

    WHERE p.player_id NOT IN (
        SELECT i.player_id
        FROM initial_xi i
    )
),

fill_players AS (
    SELECT
        r.player_id,
        r.player_name,
        r.role,
        r.match_score,
        r.can_keep,
        r.can_bat,
        r.can_bowl,
        r.top_order

    FROM remaining r

    WHERE r.rn <= GREATEST(
        0,
        11 - (
            SELECT COUNT(*)
            FROM initial_xi
        )
    )
),

final_xi AS (
    SELECT * FROM initial_xi

    UNION

    SELECT * FROM fill_players
)

SELECT
    f.player_id,
    f.player_name::VARCHAR,
    f.role::VARCHAR,
    f.match_score::NUMERIC,
    f.can_keep,
    f.can_bat,
    f.can_bowl,
    f.top_order,

    CASE
        WHEN f.can_keep
            THEN 'Wicketkeeper'

        WHEN f.top_order
            THEN 'Top-order option'

        WHEN f.can_bowl
            THEN 'Bowling option'

        ELSE
            'Best match performer'
    END::VARCHAR AS selection_reason

FROM final_xi f

ORDER BY f.match_score DESC;

$$;


ALTER FUNCTION public.suggest_match_playing_xi(input_team character varying, input_opponent character varying, input_venue text) OWNER TO cricket_admin;

--
-- Name: suggest_playing_xi(character varying); Type: FUNCTION; Schema: public; Owner: cricket_admin
--

CREATE FUNCTION public.suggest_playing_xi(input_team character varying) RETURNS TABLE(player_id integer, player_name character varying, role character varying, base_selection_score numeric, can_keep boolean, can_bat boolean, genuine_bowling_option boolean, top_order_option boolean, selection_reason character varying)
    LANGUAGE sql
    AS $$

WITH pool AS (
    SELECT
        pac.player_id,
        pac.name,
        pac.role,
        pac.base_selection_score,
        pac.can_keep,
        pac.can_bat,
        pac.genuine_bowling_option,
        pac.top_order_option
    FROM player_actual_capability pac
    WHERE pac.team = input_team
),

keeper AS (
    SELECT
        p.*
    FROM pool p
    WHERE p.can_keep = TRUE
    ORDER BY p.base_selection_score DESC
    LIMIT 1
),

top_order AS (
    SELECT
        p.*
    FROM pool p
    WHERE p.top_order_option = TRUE
      AND p.player_id NOT IN (
          SELECT k.player_id
          FROM keeper k
      )
    ORDER BY p.base_selection_score DESC
    LIMIT 2
),

bowlers AS (
    SELECT
        p.*
    FROM pool p
    WHERE p.genuine_bowling_option = TRUE
      AND p.player_id NOT IN (
          SELECT k.player_id
          FROM keeper k

          UNION

          SELECT t.player_id
          FROM top_order t
      )
    ORDER BY p.base_selection_score DESC
    LIMIT 5
),

initial_selection AS (
    SELECT * FROM keeper
    UNION
    SELECT * FROM top_order
    UNION
    SELECT * FROM bowlers
),

remaining AS (
    SELECT
        p.*,
        ROW_NUMBER() OVER (
            ORDER BY p.base_selection_score DESC
        ) AS rn
    FROM pool p
    WHERE p.player_id NOT IN (
        SELECT i.player_id
        FROM initial_selection i
    )
),

final_fill AS (
    SELECT
        r.player_id,
        r.name,
        r.role,
        r.base_selection_score,
        r.can_keep,
        r.can_bat,
        r.genuine_bowling_option,
        r.top_order_option
    FROM remaining r
    WHERE r.rn <= GREATEST(
        0,
        11 - (
            SELECT COUNT(*)
            FROM initial_selection
        )
    )
),

final_xi AS (
    SELECT * FROM initial_selection
    UNION
    SELECT * FROM final_fill
)

SELECT
    fx.player_id,
    fx.name::VARCHAR AS player_name,
    fx.role::VARCHAR,
    fx.base_selection_score::NUMERIC,
    fx.can_keep,
    fx.can_bat,
    fx.genuine_bowling_option,
    fx.top_order_option,

    CASE
        WHEN fx.can_keep = TRUE
            THEN 'Wicketkeeper'
        WHEN fx.top_order_option = TRUE
            THEN 'Top-order option'
        WHEN fx.genuine_bowling_option = TRUE
            THEN 'Bowling option'
        ELSE
            'Best remaining performer'
    END::VARCHAR AS selection_reason

FROM final_xi fx

ORDER BY
    fx.base_selection_score DESC;

$$;


ALTER FUNCTION public.suggest_playing_xi(input_team character varying) OWNER TO cricket_admin;

