--
-- Name: active_player_pool; Type: VIEW; Schema: public; Owner: cricket_admin
--

CREATE VIEW public.active_player_pool AS
 WITH last_played AS (
         SELECT x.player_id,
            max(x.match_date) AS last_match_date
           FROM ( SELECT b.player_id,
                    m.match_date
                   FROM (public.batting_match_stats b
                     JOIN public.matches m ON ((b.match_id = m.match_id)))
                UNION ALL
                 SELECT bw.player_id,
                    m.match_date
                   FROM (public.bowling_match_stats bw
                     JOIN public.matches m ON ((bw.match_id = m.match_id)))) x
          GROUP BY x.player_id
        )
 SELECT p.player_id,
    p.name,
    p.team,
    p.role,
    lp.last_match_date,
        CASE
            WHEN (lp.last_match_date >= (CURRENT_DATE - '6 mons'::interval)) THEN 100.00
            WHEN (lp.last_match_date >= (CURRENT_DATE - '1 year'::interval)) THEN 85.00
            WHEN (lp.last_match_date IS NOT NULL) THEN 65.00
            ELSE 50.00
        END AS activity_score,
        CASE
            WHEN (lp.last_match_date >= (CURRENT_DATE - '6 mons'::interval)) THEN 'Recent'::text
            WHEN (lp.last_match_date >= (CURRENT_DATE - '1 year'::interval)) THEN 'Returning'::text
            WHEN (lp.last_match_date IS NOT NULL) THEN 'Long Gap'::text
            ELSE 'No Recent T20I Data'::text
        END AS activity_status
   FROM (public.players p
     LEFT JOIN last_played lp ON ((p.player_id = lp.player_id)))
  WHERE (p.is_active = true);


ALTER VIEW public.active_player_pool OWNER TO cricket_admin;

