);


ALTER TABLE public.deliveries OWNER TO cricket_admin;

--
-- Name: batter_bowler_head_to_head; Type: VIEW; Schema: public; Owner: cricket_admin
--

CREATE VIEW public.batter_bowler_head_to_head AS
 SELECT d.batter_id,
    batter.name AS batter,
    batter.team AS batter_team,
    d.bowler_id,
    bowler.name AS bowler,
    bowler.team AS bowler_team,
    count(*) FILTER (WHERE (d.wides = 0)) AS balls_faced,
    sum(d.batter_runs) AS runs,
    count(*) FILTER (WHERE (((d.player_out)::text = (d.batter)::text) AND ((d.dismissal_type)::text <> ALL ((ARRAY['run out'::character varying, 'retired hurt'::character varying, 'retired out'::character varying, 'obstructing the field'::character varying])::text[])))) AS dismissals,
    count(*) FILTER (WHERE (d.batter_runs = 4)) AS fours,
    count(*) FILTER (WHERE (d.batter_runs = 6)) AS sixes,
    round((((sum(d.batter_runs))::numeric * (100)::numeric) / (NULLIF(count(*) FILTER (WHERE (d.wides = 0)), 0))::numeric), 2) AS strike_rate
   FROM ((public.deliveries d
     JOIN public.players batter ON ((d.batter_id = batter.player_id)))
     JOIN public.players bowler ON ((d.bowler_id = bowler.player_id)))
  GROUP BY d.batter_id, batter.name, batter.team, d.bowler_id, bowler.name, bowler.team;


ALTER VIEW public.batter_bowler_head_to_head OWNER TO cricket_admin;

--
-- Name: batter_phase_stats; Type: VIEW; Schema: public; Owner: cricket_admin
--

CREATE VIEW public.batter_phase_stats AS
 SELECT d.batter_id AS player_id,
    p.name,
    p.team,
    d.phase,
    count(*) FILTER (WHERE (d.wides = 0)) AS balls_faced,
    sum(d.batter_runs) AS runs,
    count(*) FILTER (WHERE (d.batter_runs = 4)) AS fours,
    count(*) FILTER (WHERE (d.batter_runs = 6)) AS sixes,
    round((((sum(d.batter_runs))::numeric * (100)::numeric) / (NULLIF(count(*) FILTER (WHERE (d.wides = 0)), 0))::numeric), 2) AS strike_rate
   FROM (public.deliveries d
     JOIN public.players p ON ((d.batter_id = p.player_id)))
  GROUP BY d.batter_id, p.name, p.team, d.phase;


ALTER VIEW public.batter_phase_stats OWNER TO cricket_admin;

