--
-- Name: batting_position_performance; Type: VIEW; Schema: public; Owner: cricket_admin
--

CREATE VIEW public.batting_position_performance AS
 WITH first_appearance AS (
         SELECT d.match_id,
            d.innings,
            d.batter_id,
            d.batting_team,
            min(d.delivery_id) AS first_delivery_id
           FROM public.deliveries d
          WHERE (d.batter_id IS NOT NULL)
          GROUP BY d.match_id, d.innings, d.batter_id, d.batting_team
        ), positions AS (
         SELECT first_appearance.match_id,
            first_appearance.innings,
            first_appearance.batter_id,
            first_appearance.batting_team,
            row_number() OVER (PARTITION BY first_appearance.match_id, first_appearance.innings ORDER BY first_appearance.first_delivery_id) AS batting_position
           FROM first_appearance
        ), innings_stats AS (
         SELECT b.match_id,
            b.innings,
            b.player_id,
            b.team,
            b.runs,
            b.balls_faced,
            b.dismissed,
            p_1.batting_position
           FROM (public.batting_match_stats b
             JOIN positions p_1 ON (((b.match_id = p_1.match_id) AND (b.innings = p_1.innings) AND (b.player_id = p_1.batter_id))))
        )
 SELECT i.player_id,
    p.name,
    p.team,
    i.batting_position,
    count(*) AS innings,
    sum(i.runs) AS runs,
    sum(i.balls_faced) AS balls_faced,
    count(*) FILTER (WHERE (i.dismissed = true)) AS dismissals,
    round(((sum(i.runs))::numeric / (NULLIF(count(*) FILTER (WHERE (i.dismissed = true)), 0))::numeric), 2) AS batting_average,
    round((((sum(i.runs))::numeric * (100)::numeric) / (NULLIF(sum(i.balls_faced), 0))::numeric), 2) AS strike_rate
   FROM (innings_stats i
     JOIN public.players p ON ((i.player_id = p.player_id)))
  GROUP BY i.player_id, p.name, p.team, i.batting_position;


ALTER VIEW public.batting_position_performance OWNER TO cricket_admin;

--
-- Name: bowler_phase_stats; Type: VIEW; Schema: public; Owner: cricket_admin
--

CREATE VIEW public.bowler_phase_stats AS
 SELECT d.bowler_id AS player_id,
    p.name,
    p.team,
    d.phase,
    count(*) FILTER (WHERE ((d.wides = 0) AND (d.no_balls = 0))) AS balls_bowled,
    sum(((d.total_runs - d.byes) - d.leg_byes)) AS runs_conceded,
    count(*) FILTER (WHERE ((d.is_wicket = true) AND ((d.dismissal_type)::text <> ALL ((ARRAY['run out'::character varying, 'retired hurt'::character varying, 'retired out'::character varying, 'obstructing the field'::character varying])::text[])))) AS wickets,
    count(*) FILTER (WHERE (d.total_runs = 0)) AS dot_balls,
    round((((sum(((d.total_runs - d.byes) - d.leg_byes)))::numeric * (6)::numeric) / (NULLIF(count(*) FILTER (WHERE ((d.wides = 0) AND (d.no_balls = 0))), 0))::numeric), 2) AS economy
   FROM (public.deliveries d
     JOIN public.players p ON ((d.bowler_id = p.player_id)))
  GROUP BY d.bowler_id, p.name, p.team, d.phase;


ALTER VIEW public.bowler_phase_stats OWNER TO cricket_admin;

