--
-- Name: eligible_current_players; Type: VIEW; Schema: public; Owner: cricket_admin
--

CREATE VIEW public.eligible_current_players AS
 WITH last_played AS (
         SELECT x.player_id,
            max(x.match_date) AS last_match_date
           FROM ( SELECT b.player_id,
                    m.match_date
                   FROM (public.batting_match_stats b
                     JOIN public.matches m ON ((b.match_id = m.match_id)))
                UNION
                 SELECT bw.player_id,
                    m.match_date
                   FROM (public.bowling_match_stats bw
                     JOIN public.matches m ON ((bw.match_id = m.match_id)))) x
          GROUP BY x.player_id
        )
 SELECT p.player_id,
    p.name,
    p.team,
    p.role,
    p.is_active,
    l.last_match_date
   FROM (public.players p
     LEFT JOIN last_played l ON ((p.player_id = l.player_id)))
  WHERE ((p.is_active = true) AND (l.last_match_date >= (CURRENT_DATE - '6 mons'::interval)));


ALTER VIEW public.eligible_current_players OWNER TO cricket_admin;

--
-- Name: historical_h2h_form; Type: VIEW; Schema: public; Owner: cricket_admin
--

CREATE VIEW public.historical_h2h_form AS
 WITH completed_matches AS (
         SELECT m.match_id,
            m.match_date,
            m.team1,
            m.team2,
            m.winner
           FROM public.matches m
          WHERE (m.winner IS NOT NULL)
        ), h2h AS (
         SELECT cm.match_id,
            count(pm.match_id) AS previous_h2h_matches,
            count(pm.match_id) FILTER (WHERE ((pm.winner)::text = (cm.team1)::text)) AS team1_previous_wins,
            count(pm.match_id) FILTER (WHERE ((pm.winner)::text = (cm.team2)::text)) AS team2_previous_wins
           FROM (completed_matches cm
             LEFT JOIN completed_matches pm ON ((((((pm.team1)::text = (cm.team1)::text) AND ((pm.team2)::text = (cm.team2)::text)) OR (((pm.team1)::text = (cm.team2)::text) AND ((pm.team2)::text = (cm.team1)::text))) AND ((pm.match_date < cm.match_date) OR ((pm.match_date = cm.match_date) AND (pm.match_id < cm.match_id))))))
          GROUP BY cm.match_id
        )
 SELECT match_id,
    previous_h2h_matches,
    team1_previous_wins,
    team2_previous_wins,
    round((((team1_previous_wins)::numeric * (100)::numeric) / (NULLIF(previous_h2h_matches, 0))::numeric), 2) AS team1_h2h_win_percentage,
    round((((team2_previous_wins)::numeric * (100)::numeric) / (NULLIF(previous_h2h_matches, 0))::numeric), 2) AS team2_h2h_win_percentage
   FROM h2h;


ALTER VIEW public.historical_h2h_form OWNER TO cricket_admin;

--
-- Name: historical_player_batting_form; Type: VIEW; Schema: public; Owner: cricket_admin
--

CREATE VIEW public.historical_player_batting_form AS
 WITH player_match_batting AS (
         SELECT d.match_id,
            m.match_date,
            d.batter_id AS player_id,
            sum(d.batter_runs) AS runs,
            count(*) FILTER (WHERE (COALESCE(d.wides, 0) = 0)) AS balls_faced
           FROM (public.deliveries d
             JOIN public.matches m ON ((d.match_id = m.match_id)))
          WHERE (d.batter_id IS NOT NULL)
          GROUP BY d.match_id, m.match_date, d.batter_id
        ), historical AS (
         SELECT current_player.match_id,
            current_player.player_id,
            count(previous_player.match_id) AS previous_innings_used,
            COALESCE(sum(previous_player.runs), (0)::numeric) AS runs_previous_5,
            COALESCE(sum(previous_player.balls_faced), (0)::numeric) AS balls_previous_5
           FROM (player_match_batting current_player
             LEFT JOIN LATERAL ( SELECT previous_match.match_id,
                    previous_match.runs,
                    previous_match.balls_faced
                   FROM player_match_batting previous_match
                  WHERE ((previous_match.player_id = current_player.player_id) AND ((previous_match.match_date < current_player.match_date) OR ((previous_match.match_date = current_player.match_date) AND (previous_match.match_id < current_player.match_id))))
                  ORDER BY previous_match.match_date DESC, previous_match.match_id DESC
                 LIMIT 5) previous_player ON (true))
          GROUP BY current_player.match_id, current_player.player_id
        )
 SELECT h.match_id,
    h.player_id,
    p.name,
    p.team,
    h.previous_innings_used,
    h.runs_previous_5,
    h.balls_previous_5,
    round((h.runs_previous_5 / (NULLIF(h.previous_innings_used, 0))::numeric), 2) AS batting_avg_runs_previous_5,
    round(((h.runs_previous_5 * (100)::numeric) / NULLIF(h.balls_previous_5, (0)::numeric)), 2) AS batting_sr_previous_5
   FROM (historical h
     JOIN public.players p ON ((h.player_id = p.player_id)));


ALTER VIEW public.historical_player_batting_form OWNER TO cricket_admin;

--
-- Name: historical_player_bowling_form; Type: VIEW; Schema: public; Owner: cricket_admin
--

CREATE VIEW public.historical_player_bowling_form AS
 WITH player_match_bowling AS (
         SELECT d.match_id,
            m.match_date,
            d.bowler_id AS player_id,
            count(*) FILTER (WHERE ((COALESCE(d.wides, 0) = 0) AND (COALESCE(d.no_balls, 0) = 0))) AS legal_balls,
            sum(((d.total_runs - COALESCE(d.byes, 0)) - COALESCE(d.leg_byes, 0))) AS runs_conceded,
            count(*) FILTER (WHERE ((d.is_wicket = true) AND ((d.dismissal_type)::text <> ALL ((ARRAY['run out'::character varying, 'retired hurt'::character varying, 'retired out'::character varying, 'obstructing the field'::character varying])::text[])))) AS wickets
           FROM (public.deliveries d
             JOIN public.matches m ON ((d.match_id = m.match_id)))
          WHERE (d.bowler_id IS NOT NULL)
          GROUP BY d.match_id, m.match_date, d.bowler_id
        ), historical AS (
         SELECT current_player.match_id,
            current_player.player_id,
            count(previous_player.match_id) AS previous_matches_used,
            COALESCE(sum(previous_player.legal_balls), (0)::numeric) AS balls_previous_5,
            COALESCE(sum(previous_player.runs_conceded), (0)::numeric) AS runs_conceded_previous_5,
            COALESCE(sum(previous_player.wickets), (0)::numeric) AS wickets_previous_5
           FROM (player_match_bowling current_player
             LEFT JOIN LATERAL ( SELECT previous_match.match_id,
                    previous_match.legal_balls,
                    previous_match.runs_conceded,
                    previous_match.wickets
                   FROM player_match_bowling previous_match
                  WHERE ((previous_match.player_id = current_player.player_id) AND ((previous_match.match_date < current_player.match_date) OR ((previous_match.match_date = current_player.match_date) AND (previous_match.match_id < current_player.match_id))))
                  ORDER BY previous_match.match_date DESC, previous_match.match_id DESC
                 LIMIT 5) previous_player ON (true))
          GROUP BY current_player.match_id, current_player.player_id
        )
 SELECT h.match_id,
    h.player_id,
    p.name,
    p.team,
    h.previous_matches_used,
    h.balls_previous_5,
    h.runs_conceded_previous_5,
    h.wickets_previous_5,
    round((h.wickets_previous_5 / (NULLIF(h.previous_matches_used, 0))::numeric), 2) AS avg_wickets_previous_5,
    round(((h.runs_conceded_previous_5 * (6)::numeric) / NULLIF(h.balls_previous_5, (0)::numeric)), 2) AS economy_previous_5
   FROM (historical h
     JOIN public.players p ON ((h.player_id = p.player_id)));


ALTER VIEW public.historical_player_bowling_form OWNER TO cricket_admin;

--
-- Name: historical_team_bowling_form; Type: VIEW; Schema: public; Owner: cricket_admin
--

CREATE VIEW public.historical_team_bowling_form AS
 WITH match_bowling AS (
         SELECT m.match_id,
            m.match_date,
                CASE
                    WHEN ((d.batting_team)::text = (m.team1)::text) THEN m.team2
                    ELSE m.team1
                END AS team,
            count(*) FILTER (WHERE ((d.is_wicket = true) AND ((d.dismissal_type)::text <> ALL ((ARRAY['run out'::character varying, 'retired hurt'::character varying, 'retired out'::character varying, 'obstructing the field'::character varying])::text[])))) AS wickets,
            sum(((d.total_runs - COALESCE(d.byes, 0)) - COALESCE(d.leg_byes, 0))) AS runs_conceded,
            count(*) FILTER (WHERE ((COALESCE(d.wides, 0) = 0) AND (COALESCE(d.no_balls, 0) = 0))) AS legal_balls
           FROM (public.matches m
             JOIN public.deliveries d ON ((m.match_id = d.match_id)))
          GROUP BY m.match_id, m.match_date,
                CASE
                    WHEN ((d.batting_team)::text = (m.team1)::text) THEN m.team2
                    ELSE m.team1
                END
        ), historical AS (
         SELECT cm.match_id,
            cm.team,
            count(pm.match_id) AS matches_used,
            COALESCE(sum(pm.wickets), (0)::numeric) AS total_wickets_last_5,
            round(avg(pm.wickets), 2) AS avg_wickets_last_5,
            COALESCE(sum(pm.runs_conceded), (0)::numeric) AS total_runs_conceded_last_5,
            COALESCE(sum(pm.legal_balls), (0)::numeric) AS total_legal_balls_last_5,
            round(((sum(pm.runs_conceded) * (6)::numeric) / NULLIF(sum(pm.legal_balls), (0)::numeric)), 2) AS bowling_economy_last_5
           FROM (match_bowling cm
             LEFT JOIN LATERAL ( SELECT mb.match_id,
                    mb.wickets,
                    mb.runs_conceded,
                    mb.legal_balls
                   FROM match_bowling mb
                  WHERE (((mb.team)::text = (cm.team)::text) AND ((mb.match_date < cm.match_date) OR ((mb.match_date = cm.match_date) AND (mb.match_id < cm.match_id))))
                  ORDER BY mb.match_date DESC, mb.match_id DESC
                 LIMIT 5) pm ON (true))
          GROUP BY cm.match_id, cm.team
        )
 SELECT match_id,
    team,
    matches_used,
    total_wickets_last_5,
    avg_wickets_last_5,
    total_runs_conceded_last_5,
    total_legal_balls_last_5,
    bowling_economy_last_5
   FROM historical;


ALTER VIEW public.historical_team_bowling_form OWNER TO cricket_admin;

--
-- Name: historical_team_form; Type: VIEW; Schema: public; Owner: cricket_admin
--

CREATE VIEW public.historical_team_form AS
 WITH team_matches AS (
         SELECT m.match_id,
            m.match_date,
            m.team1 AS team,
            m.team2 AS opponent,
            m.winner
           FROM public.matches m
          WHERE (m.winner IS NOT NULL)
        UNION ALL
         SELECT m.match_id,
            m.match_date,
            m.team2 AS team,
            m.team1 AS opponent,
            m.winner
           FROM public.matches m
          WHERE (m.winner IS NOT NULL)
        ), historical_form AS (
         SELECT current_match.match_id,
            current_match.team,
            count(previous_match.match_id) AS previous_matches,
            count(*) FILTER (WHERE ((previous_match.winner)::text = (current_match.team)::text)) AS previous_wins
           FROM (team_matches current_match
             LEFT JOIN LATERAL ( SELECT previous_match_1.match_id,
                    previous_match_1.winner
                   FROM team_matches previous_match_1
                  WHERE (((previous_match_1.team)::text = (current_match.team)::text) AND ((previous_match_1.match_date < current_match.match_date) OR ((previous_match_1.match_date = current_match.match_date) AND (previous_match_1.match_id < current_match.match_id))))
                  ORDER BY previous_match_1.match_date DESC, previous_match_1.match_id DESC
                 LIMIT 5) previous_match ON (true))
          GROUP BY current_match.match_id, current_match.team
        )
 SELECT match_id,
    team,
    previous_matches AS matches_used,
    previous_wins AS wins_last_5,
    round((((previous_wins)::numeric * (100)::numeric) / (NULLIF(previous_matches, 0))::numeric), 2) AS win_percentage_last_5
   FROM historical_form;


ALTER VIEW public.historical_team_form OWNER TO cricket_admin;

--
-- Name: historical_team_player_strength; Type: VIEW; Schema: public; Owner: cricket_admin
--

CREATE VIEW public.historical_team_player_strength AS
 WITH match_players AS (
         SELECT DISTINCT d.match_id,
            d.batter_id AS player_id,
            d.batting_team AS team
           FROM public.deliveries d
          WHERE (d.batter_id IS NOT NULL)
        UNION
         SELECT DISTINCT d.match_id,
            d.non_striker_id AS player_id,
            d.batting_team AS team
           FROM public.deliveries d
          WHERE (d.non_striker_id IS NOT NULL)
        UNION
         SELECT DISTINCT d.match_id,
            d.bowler_id AS player_id,
                CASE
                    WHEN ((d.batting_team)::text = (m.team1)::text) THEN m.team2
                    ELSE m.team1
                END AS team
           FROM (public.deliveries d
             JOIN public.matches m ON ((d.match_id = m.match_id)))
          WHERE (d.bowler_id IS NOT NULL)
        ), player_history AS (
         SELECT mp.match_id,
            mp.team,
            mp.player_id,
            COALESCE(hb.previous_innings_used, (0)::bigint) AS batting_history,
            COALESCE(hb.runs_previous_5, (0)::numeric) AS batting_runs,
            COALESCE(hb.balls_previous_5, (0)::numeric) AS batting_balls,
            COALESCE(hw.previous_matches_used, (0)::bigint) AS bowling_history,
            COALESCE(hw.wickets_previous_5, (0)::numeric) AS bowling_wickets,
            COALESCE(hw.runs_conceded_previous_5, (0)::numeric) AS bowling_runs,
            COALESCE(hw.balls_previous_5, (0)::numeric) AS bowling_balls
           FROM ((match_players mp
             LEFT JOIN public.historical_player_batting_form hb ON (((mp.match_id = hb.match_id) AND (mp.player_id = hb.player_id))))
             LEFT JOIN public.historical_player_bowling_form hw ON (((mp.match_id = hw.match_id) AND (mp.player_id = hw.player_id))))
        )
 SELECT match_id,
    team,
    count(DISTINCT player_id) AS players_detected,
    count(*) FILTER (WHERE (batting_history > 0)) AS players_with_batting_history,
    count(*) FILTER (WHERE (bowling_history > 0)) AS players_with_bowling_history,
    sum(batting_runs) AS xi_runs_previous_5,
    sum(batting_balls) AS xi_balls_previous_5,
    round(((sum(batting_runs) * (100)::numeric) / NULLIF(sum(batting_balls), (0)::numeric)), 2) AS xi_batting_strike_rate,
    round((sum(batting_runs) / NULLIF(sum(batting_history), (0)::numeric)), 2) AS xi_runs_per_innings,
    sum(bowling_wickets) AS xi_wickets_previous_5,
    round((sum(bowling_wickets) / NULLIF(sum(bowling_history), (0)::numeric)), 2) AS xi_wickets_per_bowling_match,
    round(((sum(bowling_runs) * (6)::numeric) / NULLIF(sum(bowling_balls), (0)::numeric)), 2) AS xi_bowling_economy
   FROM player_history
  GROUP BY match_id, team;


ALTER VIEW public.historical_team_player_strength OWNER TO cricket_admin;

--
-- Name: historical_team_scoring_form; Type: VIEW; Schema: public; Owner: cricket_admin
--

CREATE VIEW public.historical_team_scoring_form AS
 WITH match_team_runs AS (
         SELECT m.match_id,
            m.match_date,
            d.batting_team AS team,
            sum(d.total_runs) AS team_runs
           FROM (public.matches m
             JOIN public.deliveries d ON ((m.match_id = d.match_id)))
          GROUP BY m.match_id, m.match_date, d.batting_team
        ), historical AS (
         SELECT current_match.match_id,
            current_match.team,
            count(previous_match.match_id) AS matches_used,
            round(avg(previous_match.team_runs), 2) AS avg_runs_last_5
           FROM (match_team_runs current_match
             LEFT JOIN LATERAL ( SELECT previous_match_1.match_id,
                    previous_match_1.team_runs
                   FROM match_team_runs previous_match_1
                  WHERE (((previous_match_1.team)::text = (current_match.team)::text) AND ((previous_match_1.match_date < current_match.match_date) OR ((previous_match_1.match_date = current_match.match_date) AND (previous_match_1.match_id < current_match.match_id))))
                  ORDER BY previous_match_1.match_date DESC, previous_match_1.match_id DESC
                 LIMIT 5) previous_match ON (true))
          GROUP BY current_match.match_id, current_match.team
        )
 SELECT match_id,
    team,
    matches_used,
    avg_runs_last_5
   FROM historical;


ALTER VIEW public.historical_team_scoring_form OWNER TO cricket_admin;

--
-- Name: historical_venue_form; Type: VIEW; Schema: public; Owner: cricket_admin
--

CREATE VIEW public.historical_venue_form AS
 WITH team_matches AS (
         SELECT m.match_id,
            m.match_date,
            m.venue,
            m.team1 AS team,
            m.winner
           FROM public.matches m
          WHERE (m.winner IS NOT NULL)
        UNION ALL
         SELECT m.match_id,
            m.match_date,
            m.venue,
            m.team2 AS team,
            m.winner
           FROM public.matches m
          WHERE (m.winner IS NOT NULL)
        ), venue_history AS (
         SELECT cm.match_id,
            cm.team,
            count(pm.match_id) AS previous_venue_matches,
            count(pm.match_id) FILTER (WHERE ((pm.winner)::text = (cm.team)::text)) AS previous_venue_wins
           FROM (team_matches cm
             LEFT JOIN team_matches pm ON ((((pm.team)::text = (cm.team)::text) AND (pm.venue = cm.venue) AND ((pm.match_date < cm.match_date) OR ((pm.match_date = cm.match_date) AND (pm.match_id < cm.match_id))))))
          GROUP BY cm.match_id, cm.team
        )
 SELECT match_id,
    team,
    previous_venue_matches,
    previous_venue_wins,
    round((((previous_venue_wins)::numeric * (100)::numeric) / (NULLIF(previous_venue_matches, 0))::numeric), 2) AS venue_win_percentage
   FROM venue_history;


ALTER VIEW public.historical_venue_form OWNER TO cricket_admin;

--
-- Name: match_momentum; Type: VIEW; Schema: public; Owner: cricket_admin
--

CREATE VIEW public.match_momentum AS
 WITH over_summary AS (
         SELECT d.match_id,
            d.innings,
            d.batting_team,
            (d.over_number + 1) AS over_number,
            sum(d.total_runs) AS runs_in_over,
            count(*) FILTER (WHERE (d.is_wicket = true)) AS wickets_in_over
           FROM public.deliveries d
          GROUP BY d.match_id, d.innings, d.batting_team, d.over_number
        )
 SELECT match_id,
    innings,
    batting_team,
    over_number,
    runs_in_over,
    wickets_in_over,
    sum(runs_in_over) OVER (PARTITION BY match_id, innings ORDER BY over_number) AS cumulative_score,
    sum(wickets_in_over) OVER (PARTITION BY match_id, innings ORDER BY over_number) AS cumulative_wickets
   FROM over_summary;


ALTER VIEW public.match_momentum OWNER TO cricket_admin;

--
-- Name: matches_match_id_seq; Type: SEQUENCE; Schema: public; Owner: cricket_admin
--

CREATE SEQUENCE public.matches_match_id_seq
    AS integer
    START WITH 1
    INCREMENT BY 1
    NO MINVALUE
    NO MAXVALUE
    CACHE 1;


ALTER SEQUENCE public.matches_match_id_seq OWNER TO cricket_admin;

--
-- Name: matches_match_id_seq; Type: SEQUENCE OWNED BY; Schema: public; Owner: cricket_admin
--

ALTER SEQUENCE public.matches_match_id_seq OWNED BY public.matches.match_id;


--
-- Name: ml_training_dataset; Type: VIEW; Schema: public; Owner: cricket_admin
--

CREATE VIEW public.ml_training_dataset AS
 SELECT m.match_id,
    m.match_date,
    m.team1,
    m.team2,
    m.venue,
    m.toss_winner,
    m.toss_decision,
    m.winner,
        CASE
            WHEN ((m.winner)::text = (m.team1)::text) THEN 1
            WHEN ((m.winner)::text = (m.team2)::text) THEN 0
            ELSE NULL::integer
        END AS team1_win,
    tf1.matches_used AS team1_form_matches,
    tf1.wins_last_5 AS team1_wins_last_5,
    tf1.win_percentage_last_5 AS team1_win_percentage_last_5,
    tf2.matches_used AS team2_form_matches,
    tf2.wins_last_5 AS team2_wins_last_5,
    tf2.win_percentage_last_5 AS team2_win_percentage_last_5,
    ts1.matches_used AS team1_scoring_matches,
    ts1.avg_runs_last_5 AS team1_avg_runs_last_5,
    ts2.matches_used AS team2_scoring_matches,
    ts2.avg_runs_last_5 AS team2_avg_runs_last_5,
    tb1.matches_used AS team1_bowling_matches,
    tb1.total_wickets_last_5 AS team1_total_wickets_last_5,
    tb1.avg_wickets_last_5 AS team1_avg_wickets_last_5,
    tb1.bowling_economy_last_5 AS team1_bowling_economy_last_5,
    tb2.matches_used AS team2_bowling_matches,
    tb2.total_wickets_last_5 AS team2_total_wickets_last_5,
    tb2.avg_wickets_last_5 AS team2_avg_wickets_last_5,
    tb2.bowling_economy_last_5 AS team2_bowling_economy_last_5,
    h.previous_h2h_matches,
    h.team1_previous_wins,
    h.team2_previous_wins,
    h.team1_h2h_win_percentage,
    h.team2_h2h_win_percentage,
    v1.previous_venue_matches AS team1_previous_venue_matches,
    v1.previous_venue_wins AS team1_previous_venue_wins,
    v1.venue_win_percentage AS team1_venue_win_percentage,
    v2.previous_venue_matches AS team2_previous_venue_matches,
    v2.previous_venue_wins AS team2_previous_venue_wins,
    v2.venue_win_percentage AS team2_venue_win_percentage,
        CASE
            WHEN ((m.toss_winner)::text = (m.team1)::text) THEN 1
            ELSE 0
        END AS team1_won_toss,
        CASE
            WHEN ((m.toss_decision)::text = 'field'::text) THEN 1
            ELSE 0
        END AS toss_decision_field
   FROM (((((((((public.matches m
     LEFT JOIN public.historical_team_form tf1 ON (((m.match_id = tf1.match_id) AND ((m.team1)::text = (tf1.team)::text))))
     LEFT JOIN public.historical_team_form tf2 ON (((m.match_id = tf2.match_id) AND ((m.team2)::text = (tf2.team)::text))))
     LEFT JOIN public.historical_team_scoring_form ts1 ON (((m.match_id = ts1.match_id) AND ((m.team1)::text = (ts1.team)::text))))
     LEFT JOIN public.historical_team_scoring_form ts2 ON (((m.match_id = ts2.match_id) AND ((m.team2)::text = (ts2.team)::text))))
     LEFT JOIN public.historical_team_bowling_form tb1 ON (((m.match_id = tb1.match_id) AND ((m.team1)::text = (tb1.team)::text))))
     LEFT JOIN public.historical_team_bowling_form tb2 ON (((m.match_id = tb2.match_id) AND ((m.team2)::text = (tb2.team)::text))))
     LEFT JOIN public.historical_h2h_form h ON ((m.match_id = h.match_id)))
     LEFT JOIN public.historical_venue_form v1 ON (((m.match_id = v1.match_id) AND ((m.team1)::text = (v1.team)::text))))
     LEFT JOIN public.historical_venue_form v2 ON (((m.match_id = v2.match_id) AND ((m.team2)::text = (v2.team)::text))))
  WHERE (m.winner IS NOT NULL);


ALTER VIEW public.ml_training_dataset OWNER TO cricket_admin;

