    s1.xi_bowling_economy AS team1_xi_bowling_economy,
    s2.players_detected AS team2_players_detected,
    s2.players_with_batting_history AS team2_players_batting_history,
    s2.players_with_bowling_history AS team2_players_bowling_history,
    s2.xi_runs_previous_5 AS team2_xi_runs_previous_5,
    s2.xi_batting_strike_rate AS team2_xi_batting_strike_rate,
