   FROM ((public.ml_training_dataset ml
     LEFT JOIN public.historical_team_player_strength s1 ON (((ml.match_id = s1.match_id) AND ((ml.team1)::text = (s1.team)::text))))
     LEFT JOIN public.historical_team_player_strength s2 ON (((ml.match_id = s2.match_id) AND ((ml.team2)::text = (s2.team)::text))));


