--
-- Name: player_recent_form; Type: VIEW; Schema: public; Owner: cricket_admin
--

CREATE VIEW public.player_recent_form AS
 WITH recent_batting AS (
         SELECT b.player_id,
            b.match_id,
            b.runs,
            b.balls_faced,
            b.dismissed,
            row_number() OVER (PARTITION BY b.player_id ORDER BY m.match_date DESC, b.match_id DESC) AS rn
           FROM (public.batting_match_stats b
             JOIN public.matches m ON ((b.match_id = m.match_id)))
        ), batting_summary AS (
         SELECT recent_batting.player_id,
            count(*) FILTER (WHERE (recent_batting.rn <= 5)) AS batting_innings_used,
            sum(recent_batting.runs) FILTER (WHERE (recent_batting.rn <= 5)) AS total_runs_last_5_innings,
            sum(recent_batting.balls_faced) FILTER (WHERE (recent_batting.rn <= 5)) AS total_balls_last_5_innings,
            count(*) FILTER (WHERE ((recent_batting.rn <= 5) AND (recent_batting.dismissed = true))) AS dismissals_last_5_innings
           FROM recent_batting
          GROUP BY recent_batting.player_id
        ), recent_bowling AS (
         SELECT b.player_id,
            b.match_id,
            b.wickets,
            b.dot_balls,
            b.runs_conceded,
            b.balls_bowled,
            row_number() OVER (PARTITION BY b.player_id ORDER BY m.match_date DESC, b.match_id DESC) AS rn
           FROM (public.bowling_match_stats b
             JOIN public.matches m ON ((b.match_id = m.match_id)))
        ), bowling_summary AS (
         SELECT recent_bowling.player_id,
            count(*) FILTER (WHERE (recent_bowling.rn <= 5)) AS bowling_matches_used,
            sum(recent_bowling.wickets) FILTER (WHERE (recent_bowling.rn <= 5)) AS total_wickets_last_5_matches,
            sum(recent_bowling.dot_balls) FILTER (WHERE (recent_bowling.rn <= 5)) AS total_dot_balls,
            sum(recent_bowling.runs_conceded) FILTER (WHERE (recent_bowling.rn <= 5)) AS total_runs_conceded,
            sum(recent_bowling.balls_bowled) FILTER (WHERE (recent_bowling.rn <= 5)) AS total_balls_bowled
           FROM recent_bowling
          GROUP BY recent_bowling.player_id
        )
 SELECT p.player_id,
    p.name,
    p.team,
    p.role,
    COALESCE(bs.batting_innings_used, (0)::bigint) AS batting_innings_used,
    COALESCE(bs.total_runs_last_5_innings, (0)::bigint) AS total_runs_last_5_innings,
    COALESCE(bs.dismissals_last_5_innings, (0)::bigint) AS dismissals_last_5_innings,
    round(((bs.total_runs_last_5_innings)::numeric / (NULLIF(bs.dismissals_last_5_innings, 0))::numeric), 2) AS batting_average,
    round((((bs.total_runs_last_5_innings)::numeric * (100)::numeric) / (NULLIF(bs.total_balls_last_5_innings, 0))::numeric), 2) AS batting_strike_rate,
    COALESCE(bw.bowling_matches_used, (0)::bigint) AS bowling_matches_used,
    COALESCE(bw.total_wickets_last_5_matches, (0)::bigint) AS total_wickets_last_5_matches,
    COALESCE(bw.total_dot_balls, (0)::bigint) AS total_dot_balls,
    round((((bw.total_runs_conceded)::numeric * (6)::numeric) / (NULLIF(bw.total_balls_bowled, 0))::numeric), 2) AS bowling_economy
   FROM ((public.players p
     LEFT JOIN batting_summary bs ON ((p.player_id = bs.player_id)))
     LEFT JOIN bowling_summary bw ON ((p.player_id = bw.player_id)));


ALTER VIEW public.player_recent_form OWNER TO cricket_admin;

--
-- Name: player_performance_score; Type: VIEW; Schema: public; Owner: cricket_admin
--

CREATE VIEW public.player_performance_score AS
 WITH raw_scores AS (
         SELECT player_recent_form.player_id,
            player_recent_form.name,
            player_recent_form.team,
            player_recent_form.role,
            player_recent_form.total_runs_last_5_innings,
            player_recent_form.batting_average,
            player_recent_form.batting_strike_rate,
            player_recent_form.total_wickets_last_5_matches,
            player_recent_form.total_dot_balls,
            player_recent_form.bowling_economy,
                CASE
                    WHEN ((player_recent_form.role)::text = ANY ((ARRAY['Batter'::character varying, 'Opening Batter'::character varying, 'Wicketkeeper Batter'::character varying])::text[])) THEN (((COALESCE(player_recent_form.total_runs_last_5_innings, (0)::bigint))::numeric + COALESCE(player_recent_form.batting_strike_rate, (0)::numeric)) + COALESCE(player_recent_form.batting_average, (0)::numeric))
                    WHEN ((player_recent_form.role)::text = ANY ((ARRAY['Allrounder'::character varying, 'Batting Allrounder'::character varying, 'Bowling Allrounder'::character varying])::text[])) THEN (((((COALESCE(player_recent_form.total_runs_last_5_innings, (0)::bigint))::numeric + COALESCE(player_recent_form.batting_strike_rate, (0)::numeric)) + COALESCE(player_recent_form.batting_average, (0)::numeric)) + ((COALESCE(player_recent_form.total_wickets_last_5_matches, (0)::bigint) * 20))::numeric) + (COALESCE(player_recent_form.total_dot_balls, (0)::bigint))::numeric)
                    WHEN ((player_recent_form.role)::text = 'Bowler'::text) THEN ((((COALESCE(player_recent_form.total_wickets_last_5_matches, (0)::bigint) * 25) + COALESCE(player_recent_form.total_dot_balls, (0)::bigint)))::numeric +
                    CASE
                        WHEN (player_recent_form.bowling_economy IS NOT NULL) THEN (GREATEST((0)::numeric, ((12)::numeric - player_recent_form.bowling_economy)) * (10)::numeric)
                        ELSE (0)::numeric
                    END)
                    ELSE ((COALESCE(player_recent_form.total_runs_last_5_innings, (0)::bigint) + (COALESCE(player_recent_form.total_wickets_last_5_matches, (0)::bigint) * 20)))::numeric
                END AS raw_score,
                CASE
                    WHEN ((player_recent_form.role)::text = ANY ((ARRAY['Batter'::character varying, 'Opening Batter'::character varying])::text[])) THEN 'Batter'::text
                    WHEN ((player_recent_form.role)::text = 'Wicketkeeper Batter'::text) THEN 'Wicketkeeper'::text
                    WHEN ((player_recent_form.role)::text = ANY ((ARRAY['Allrounder'::character varying, 'Batting Allrounder'::character varying, 'Bowling Allrounder'::character varying])::text[])) THEN 'Allrounder'::text
                    WHEN ((player_recent_form.role)::text = 'Bowler'::text) THEN 'Bowler'::text
                    ELSE 'Other'::text
                END AS role_group
           FROM public.player_recent_form
        ), ranked AS (
         SELECT raw_scores.player_id,
            raw_scores.name,
            raw_scores.team,
            raw_scores.role,
            raw_scores.total_runs_last_5_innings,
            raw_scores.batting_average,
            raw_scores.batting_strike_rate,
            raw_scores.total_wickets_last_5_matches,
            raw_scores.total_dot_balls,
            raw_scores.bowling_economy,
            raw_scores.raw_score,
            raw_scores.role_group,
            percent_rank() OVER (PARTITION BY raw_scores.role_group ORDER BY raw_scores.raw_score) AS percentile
           FROM raw_scores
        )
 SELECT player_id,
    name,
    team,
    role,
    role_group,
    total_runs_last_5_innings,
    batting_average,
    batting_strike_rate,
    total_wickets_last_5_matches,
    total_dot_balls,
    bowling_economy,
    round((((50)::double precision + (percentile * (50)::double precision)))::numeric, 2) AS performance_score
   FROM ranked;


ALTER VIEW public.player_performance_score OWNER TO cricket_admin;

--
-- Name: player_actual_capability; Type: VIEW; Schema: public; Owner: cricket_admin
--

CREATE VIEW public.player_actual_capability AS
 SELECT ap.player_id,
    ap.name,
    ap.team,
    ap.role,
    ap.last_match_date,
    ap.activity_status,
    ap.activity_score,
    COALESCE(pps.performance_score, (0)::numeric) AS performance_score,
    round(((COALESCE(pps.performance_score, (0)::numeric) * 0.80) + (COALESCE(ap.activity_score, (0)::numeric) * 0.20)), 2) AS base_selection_score,
        CASE
            WHEN ((ap.role)::text = ANY ((ARRAY['Wicketkeeper'::character varying, 'Wicketkeeper Batter'::character varying])::text[])) THEN true
            ELSE false
        END AS can_keep,
        CASE
            WHEN ((ap.role)::text = ANY ((ARRAY['Batter'::character varying, 'Opening Batter'::character varying, 'Top order Batter'::character varying, 'Middle order Batter'::character varying, 'Wicketkeeper Batter'::character varying, 'Allrounder'::character varying, 'Batting Allrounder'::character varying, 'Bowling Allrounder'::character varying])::text[])) THEN true
            ELSE false
        END AS can_bat,
        CASE
            WHEN ((ap.role)::text = ANY ((ARRAY['Bowler'::character varying, 'Allrounder'::character varying, 'Bowling Allrounder'::character varying, 'Batting Allrounder'::character varying])::text[])) THEN true
            ELSE false
        END AS can_bowl,
        CASE
            WHEN ((ap.role)::text = ANY ((ARRAY['Bowler'::character varying, 'Allrounder'::character varying, 'Bowling Allrounder'::character varying, 'Batting Allrounder'::character varying])::text[])) THEN true
            ELSE false
        END AS genuine_bowling_option,
        CASE
            WHEN ((ap.role)::text = ANY ((ARRAY['Opening Batter'::character varying, 'Top order Batter'::character varying])::text[])) THEN true
            ELSE false
        END AS top_order_option
   FROM (public.active_player_pool ap
     LEFT JOIN public.player_performance_score pps ON ((ap.player_id = pps.player_id)));


ALTER VIEW public.player_actual_capability OWNER TO cricket_admin;

--
-- Name: player_selection_score; Type: VIEW; Schema: public; Owner: cricket_admin
--

CREATE VIEW public.player_selection_score AS
 SELECT player_id,
    name,
    team,
    role,
    last_match_date,
    activity_status,
    activity_score,
    performance_score,
    base_selection_score,
    can_keep,
    can_bat,
    can_bowl,
    genuine_bowling_option,
    top_order_option
   FROM public.player_actual_capability;


