--
-- Name: team_recent_strength; Type: VIEW; Schema: public; Owner: cricket_admin
--

CREATE VIEW public.team_recent_strength AS
 WITH innings_scores AS (
         SELECT d.match_id,
            d.innings,
            d.batting_team AS team,
            m.match_date,
            sum(d.total_runs) AS team_score,
            count(*) FILTER (WHERE (d.is_wicket = true)) AS wickets_lost
           FROM (public.deliveries d
             JOIN public.matches m ON ((d.match_id = m.match_id)))
          WHERE (m.winner IS NOT NULL)
          GROUP BY d.match_id, d.innings, d.batting_team, m.match_date
        ), team_matches AS (
         SELECT i.match_id,
            i.match_date,
            i.team,
            i.team_score,
                CASE
                    WHEN ((i.team)::text = (m.team1)::text) THEN m.team2
                    ELSE m.team1
                END AS opponent,
            opp.wickets_lost AS wickets_taken
           FROM ((innings_scores i
             JOIN public.matches m ON ((i.match_id = m.match_id)))
             JOIN innings_scores opp ON (((i.match_id = opp.match_id) AND (i.innings <> opp.innings))))
          WHERE (m.winner IS NOT NULL)
        ), ranked_matches AS (
         SELECT team_matches.match_id,
            team_matches.match_date,
            team_matches.team,
            team_matches.team_score,
            team_matches.opponent,
            team_matches.wickets_taken,
            row_number() OVER (PARTITION BY team_matches.team ORDER BY team_matches.match_date DESC, team_matches.match_id DESC) AS rn
           FROM team_matches
        ), last_5 AS (
         SELECT ranked_matches.match_id,
            ranked_matches.match_date,
            ranked_matches.team,
            ranked_matches.team_score,
            ranked_matches.opponent,
            ranked_matches.wickets_taken,
            ranked_matches.rn
           FROM ranked_matches
          WHERE (ranked_matches.rn <= 5)
        ), batting_wickets AS (
         SELECT last_5.team,
            count(*) AS matches_used,
            sum(last_5.team_score) AS total_runs_last_5_matches,
            round(avg(last_5.team_score), 2) AS avg_score_last_5_matches,
            sum(last_5.wickets_taken) AS wickets_last_5_matches
           FROM last_5
          GROUP BY last_5.team
        ), bowling AS (
         SELECT b.team,
            round((((sum(b.runs_conceded))::numeric * (6)::numeric) / (NULLIF(sum(b.balls_bowled), 0))::numeric), 2) AS economy_last_5_matches,
            sum(b.dot_balls) AS dot_balls_last_5_matches
           FROM (public.bowling_match_stats b
             JOIN last_5 l ON ((((b.team)::text = (l.team)::text) AND (b.match_id = l.match_id))))
          GROUP BY b.team
        )
 SELECT bw.team,
    bw.matches_used,
    bw.total_runs_last_5_matches,
    bw.avg_score_last_5_matches,
    bw.wickets_last_5_matches,
    bl.economy_last_5_matches,
    bl.dot_balls_last_5_matches
   FROM (batting_wickets bw
     LEFT JOIN bowling bl ON (((bw.team)::text = (bl.team)::text)));


ALTER VIEW public.team_recent_strength OWNER TO cricket_admin;

--
-- Name: team_strength_score; Type: VIEW; Schema: public; Owner: cricket_admin
--

CREATE VIEW public.team_strength_score AS
 SELECT team,
    round((((COALESCE(avg_score_last_5_matches, (140)::numeric) * 0.4) + (COALESCE(wickets_last_5_matches, (0)::numeric) * (5)::numeric)) + (GREATEST((0)::numeric, ((12)::numeric - COALESCE(economy_last_5_matches, (9)::numeric))) * (5)::numeric)), 2) AS team_strength_score
   FROM public.team_recent_strength;


ALTER VIEW public.team_strength_score OWNER TO cricket_admin;

--
-- Name: team_toss_situation_stats; Type: VIEW; Schema: public; Owner: cricket_admin
--

CREATE VIEW public.team_toss_situation_stats AS
 WITH team_matches AS (
         SELECT m.match_id,
            m.match_date,
            m.team1 AS team,
            m.team1,
            m.team2,
            m.toss_winner,
            m.toss_decision,
            m.winner
           FROM public.matches m
          WHERE (m.winner IS NOT NULL)
        UNION ALL
         SELECT m.match_id,
            m.match_date,
            m.team2 AS team,
            m.team1,
            m.team2,
            m.toss_winner,
            m.toss_decision,
            m.winner
           FROM public.matches m
          WHERE (m.winner IS NOT NULL)
        ), match_context AS (
         SELECT team_matches.match_id,
            team_matches.match_date,
            team_matches.team,
            team_matches.winner,
                CASE
                    WHEN ((team_matches.toss_winner)::text = (team_matches.team)::text) THEN 'Won Toss'::text
                    ELSE 'Lost Toss'::text
                END AS toss_result,
                CASE
                    WHEN ((((team_matches.toss_winner)::text = (team_matches.team)::text) AND ((team_matches.toss_decision)::text = 'bat'::text)) OR (((team_matches.toss_winner)::text <> (team_matches.team)::text) AND ((team_matches.toss_decision)::text = 'field'::text))) THEN 'Batting First'::text
                    ELSE 'Chasing'::text
                END AS batting_situation
           FROM team_matches
        )
 SELECT team,
    toss_result,
    batting_situation,
    count(*) AS matches_played,
    count(*) FILTER (WHERE ((winner)::text = (team)::text)) AS matches_won,
    count(*) FILTER (WHERE ((winner)::text <> (team)::text)) AS matches_lost,
    round((((count(*) FILTER (WHERE ((winner)::text = (team)::text)))::numeric * (100)::numeric) / (NULLIF(count(*), 0))::numeric), 2) AS win_percentage
   FROM match_context
  GROUP BY team, toss_result, batting_situation;


ALTER VIEW public.team_toss_situation_stats OWNER TO cricket_admin;

--
-- Name: team_venue_stats; Type: VIEW; Schema: public; Owner: cricket_admin
--

CREATE VIEW public.team_venue_stats AS
 WITH team_matches AS (
         SELECT m.match_id,
            m.match_date,
            m.venue,
            m.team1 AS team,
            m.winner
           FROM public.matches m
          WHERE (m.winner IS NOT NULL)
        UNION ALL
         SELECT m.match_id,
            m.match_date,
            m.venue,
            m.team2 AS team,
            m.winner
           FROM public.matches m
          WHERE (m.winner IS NOT NULL)
        )
 SELECT team,
    venue,
    count(*) AS matches_played,
    count(*) FILTER (WHERE ((winner)::text = (team)::text)) AS matches_won,
    count(*) FILTER (WHERE ((winner)::text <> (team)::text)) AS matches_lost,
    round((((count(*) FILTER (WHERE ((winner)::text = (team)::text)))::numeric * (100)::numeric) / (NULLIF(count(*), 0))::numeric), 2) AS win_percentage
   FROM team_matches
  GROUP BY team, venue;


ALTER VIEW public.team_venue_stats OWNER TO cricket_admin;

--
-- Name: team_vs_team_stats; Type: VIEW; Schema: public; Owner: cricket_admin
--

CREATE VIEW public.team_vs_team_stats AS
 WITH normalized_matches AS (
         SELECT matches.match_id,
            matches.match_date,
            matches.winner,
            LEAST(matches.team1, matches.team2) AS team_a,
            GREATEST(matches.team1, matches.team2) AS team_b
           FROM public.matches
          WHERE (matches.winner IS NOT NULL)
        ), innings_scores AS (
         SELECT d.match_id,
            d.innings,
            d.batting_team,
            sum(d.total_runs) AS team_score
           FROM public.deliveries d
          GROUP BY d.match_id, d.innings, d.batting_team
        ), match_scores AS (
         SELECT n.match_id,
            n.match_date,
            n.team_a,
            n.team_b,
            n.winner,
            max(
                CASE
                    WHEN ((i.batting_team)::text = (n.team_a)::text) THEN i.team_score
                    ELSE NULL::bigint
                END) AS team_a_score,
            max(
                CASE
                    WHEN ((i.batting_team)::text = (n.team_b)::text) THEN i.team_score
                    ELSE NULL::bigint
                END) AS team_b_score
           FROM (normalized_matches n
             JOIN innings_scores i ON ((n.match_id = i.match_id)))
          GROUP BY n.match_id, n.match_date, n.team_a, n.team_b, n.winner
        )
 SELECT team_a,
    team_b,
    count(*) AS matches_played,
    count(*) FILTER (WHERE ((winner)::text = (team_a)::text)) AS team_a_wins,
    count(*) FILTER (WHERE ((winner)::text = (team_b)::text)) AS team_b_wins,
    round((((count(*) FILTER (WHERE ((winner)::text = (team_a)::text)))::numeric * (100)::numeric) / (NULLIF(count(*), 0))::numeric), 2) AS team_a_win_percentage,
    round((((count(*) FILTER (WHERE ((winner)::text = (team_b)::text)))::numeric * (100)::numeric) / (NULLIF(count(*), 0))::numeric), 2) AS team_b_win_percentage,
    round(avg(team_a_score), 2) AS team_a_average_score,
    round(avg(team_b_score), 2) AS team_b_average_score,
    max(team_a_score) AS team_a_highest_score,
    max(team_b_score) AS team_b_highest_score
   FROM match_scores
  GROUP BY team_a, team_b;


ALTER VIEW public.team_vs_team_stats OWNER TO cricket_admin;

--
-- Name: venue_stats; Type: VIEW; Schema: public; Owner: cricket_admin
--

CREATE VIEW public.venue_stats AS
 WITH innings_scores AS (
         SELECT d.match_id,
            d.innings,
            m.venue,
            sum(d.total_runs) AS innings_score
           FROM (public.deliveries d
             JOIN public.matches m ON ((d.match_id = m.match_id)))
          GROUP BY d.match_id, d.innings, m.venue
        ), match_context AS (
         SELECT m.match_id,
            m.venue,
            m.team1,
            m.team2,
            m.toss_winner,
            m.toss_decision,
            m.winner,
                CASE
                    WHEN ((m.toss_decision)::text = 'bat'::text) THEN m.toss_winner
                    ELSE
                    CASE
                        WHEN ((m.toss_winner)::text = (m.team1)::text) THEN m.team2
                        ELSE m.team1
                    END
                END AS batting_first_team
           FROM public.matches m
          WHERE (m.winner IS NOT NULL)
        ), match_scores AS (
         SELECT mc.match_id,
            mc.venue,
            mc.winner,
            mc.batting_first_team,
            max(
                CASE
                    WHEN (i.innings = 1) THEN i.innings_score
                    ELSE NULL::bigint
                END) AS first_innings_score
           FROM (match_context mc
             JOIN innings_scores i ON ((mc.match_id = i.match_id)))
          GROUP BY mc.match_id, mc.venue, mc.winner, mc.batting_first_team
        )
 SELECT venue,
    count(*) AS matches_played,
    round(avg(first_innings_score), 2) AS avg_first_innings_score,
    count(*) FILTER (WHERE ((winner)::text = (batting_first_team)::text)) AS defending_wins,
    count(*) FILTER (WHERE ((winner)::text <> (batting_first_team)::text)) AS chasing_wins,
    round((((count(*) FILTER (WHERE ((winner)::text = (batting_first_team)::text)))::numeric * (100)::numeric) / (NULLIF(count(*), 0))::numeric), 2) AS defending_win_percentage,
    round((((count(*) FILTER (WHERE ((winner)::text <> (batting_first_team)::text)))::numeric * (100)::numeric) / (NULLIF(count(*), 0))::numeric), 2) AS chasing_win_percentage
   FROM match_scores
  GROUP BY venue;


ALTER VIEW public.venue_stats OWNER TO cricket_admin;

